select case when age >= 58 then 'LARGE' else 'SMALL' end as age_tier, count(case when city = 'London' then 1 end) as london_count, count(distinct id) as distinct_ids, sum(case when country = 'SG' then age else 0 end) as sg_age, stddev_samp(age) as age_stddev, size(collect_set(segment)) as num_segments, approx_percentile(credit_limit, 0.9) as credit_limit_p90 from customers group by case when age >= 58 then 'LARGE' else 'SMALL' end;
